        "kimi": "charcoal",
        "zai": "graphite",
        "minimax": "rose",
        "stepfun": "sky",
        "mimo": "tangerine",
        "qwen": "cobalt",
    ]

    /// A gradient paints a character from its top left to its bottom right;
    /// its ink above is the text colour.
    static let gradients: [String: [(offset: CGFloat, color: String)]] = [
        "aurora": [(0, "#A4FFB0"), (0.42, "#00F0E4"), (1, "#2E9EF7")],
    ]

    /// FNV-1a over path and layers, so a transcription slip shows up as a
    /// mismatch in the tests instead of a character that draws wrong.
    static let shapeHashes: [String: UInt64] = [
        "whale": 1148146071659031996,
        "star": 8008129714236512596,
        "moon": 17584893466079100804,
        "wave": 18167869559215691516,
        "squircle": 14792441555880373426,
        "zed": 12199594403111449728,
        "hex": 2685432701587787403,
        "gumdrop": 9584857000087338833,
        "peanut": 16796956129233361690,
        "saucer": 18087043917136485772,
        "bunny": 15328087026644756165,
        "kitty": 5368381610256476819,
        "beacon": 1183937180954113394,
        "plus": 6888027297415739396,
        "magnet": 2364587701459341763,
        "acorn": 13119279777124588490,
        "pebbles": 5884429594627912719,
        "cushion": 1512965948075870279,
        "ring": 16771350086485700288,
        "gem": 17144535981609358033,
    ]

    // MARK: - Ink

    /// inks.js isHex: a six-digit hex is paint as it stands.
    static func isHex(_ color: String) -> Bool {
        color.count == 7 && color.hasPrefix("#") && color.dropFirst().allSatisfy(\.isHexDigit)
    }

    /// inks.js inkName: a known id, then a renamed one, else gray.
    static func inkName(_ color: String) -> String {
        if inks[color] != nil { return color }
        if let renamed = legacy[color], inks[renamed] != nil { return renamed }
        return "gray"
    }

    static func inkFill(_ color: String) -> String {
        isHex(color) ? color : "var(--bt-ink-\(inkName(color)))"
    }

    /// Text in a Bot's colour; pure black reads as a heading, so it falls to gray.
    static func inkText(_ color: String) -> String {
        color == "black" ? "var(--bt-ink-gray)" : inkFill(color)
    }

    /// A colour as a CSS background: the gradient where one exists, else the ink.
    static func paintCss(_ color: String) -> String {
        guard let stops = gradients[color] else { return inkFill(color) }
        let parts = stops.map { "\($0.color) \(number($0.offset * 100))%" }.joined(separator: ",")
        return "linear-gradient(135deg,\(parts))"
    }

    // MARK: - Markup

    /// JS prints integers without a trailing ".0", and this markup is compared as text.
    static func number(_ value: CGFloat) -> String {
        value == value.rounded() ? String(Int(value)) : String(Double(value))
    }

    static func maskBox(_ size: CGFloat) -> String {
        "maskUnits=\"userSpaceOnUse\" x=\"\(number(-size))\" y=\"\(number(-size))\" "
            + "width=\"\(number(size * 3))\" height=\"\(number(size * 3))\""
    }

    static func eyeMarkup(_ eye: Eye) -> String {
        "<g transform=\"translate(\(number(eye.cx)) \(number(eye.cy))) rotate(\(number(eye.tilt)))\">"
            + "<rect class=\"bt-eye\" x=\"\(number(-eye.width / 2))\" y=\"\(number(-eye.height / 2))\""
            + " width=\"\(number(eye.width))\" height=\"\(number(eye.height))\""
            + " rx=\"\(number(eye.width / 2))\"/></g>"
    }

    /// A closed, happy eye in the same spot, shown while the mark is petted.
    static func happyEyeMarkup(_ eye: Eye) -> String {
        "<g transform=\"translate(\(number(eye.cx)) \(number(eye.cy))) rotate(\(number(eye.tilt)))\">"
            + "<path class=\"bt-eye-happy\" opacity=\"0\""
            + " d=\"M\(number(-eye.width * 0.62)) \(number(eye.height * 0.14))"
            + "Q0 \(number(-eye.height * 0.42)) \(number(eye.width * 0.62)) \(number(eye.height * 0.14))\""
            + " fill=\"none\" stroke=\"#000\" stroke-width=\"\(number(eye.width * 0.5))\""
            + " stroke-linecap=\"round\"/></g>"
    }

    /// A mask covering three boxes, so a bob or squash never clips at the edge.
    static func holes(_ def: Shape, eyes: String) -> String {
        "<rect x=\"\(number(-def.size))\" y=\"\(number(-def.size))\""
            + " width=\"\(number(def.size * 3))\" height=\"\(number(def.size * 3))\" fill=\"#fff\"/>" + eyes
    }

    static func hasShape(_ id: String) -> Bool { shapes[id] != nil }
    static func shapeId(_ id: String) -> String { hasShape(id) ? id : fallbackShape }
    static func shapeOf(_ id: String) -> Shape { shapes[shapeId(id)]! }

    /// characters.js bodyOf: the silhouette, then the decals and the shade.
    static func bodyOf(_ def: Shape, paint: String, flat: Bool = false) -> String {
        guard let path = def.path else { return "" }
        return "<g fill-rule=\"evenodd\"><path d=\"\(path)\" fill=\"\(paint)\"/>" + (flat ? "" : def.layers) + "</g>"
    }

    /// characters.js characterMarkup. The caller picks the mask id so two marks on
    /// one screen never share it; a duplicate id stops painting once it unmounts.
    static func characterMarkup(_ shape: String, _ color: String,
                                maskId: String = CharacterMarks.maskId) -> String {
        let def = shapeOf(shape)
        let eyes = "<g class=\"bt-gaze\"><g class=\"bt-eyes\" fill=\"#000\">"
            + def.eyes.map(eyeMarkup).joined() + def.eyes.map(happyEyeMarkup).joined() + "</g></g>"
        let stops = gradients[color]
        let gradient = stops.map { stops in
            "<linearGradient id=\"\(maskId)g\" gradientUnits=\"userSpaceOnUse\""
                + " x1=\"18\" y1=\"10\" x2=\"78\" y2=\"92\">"
                + stops.map { "<stop offset=\"\(number($0.offset))\" stop-color=\"\($0.color)\"/>" }.joined()
                + "</linearGradient>"
        } ?? ""
        let paint = stops != nil ? "url(#\(maskId)g)" : inkFill(color)
        let body = "<g mask=\"url(#\(maskId))\">\(bodyOf(def, paint: paint))</g>"
        return "<defs>\(gradient)<mask id=\"\(maskId)\" \(maskBox(def.size))>"
            + "\(holes(def, eyes: eyes))</mask></defs><g class=\"bt-b\">\(body)</g>"
    }

    /// FNV-1a over the UTF-8 bytes; the generator computed the same values.
    static func hash(_ text: String) -> UInt64 {
        var value: UInt64 = 0xcbf2_9ce4_8422_2325
        for byte in Array(text.utf8) {
            value ^= UInt64(byte)
            value = value &* 0x100_0000_01b3
        }
        return value
    }
}
